# 2️⃣  Custom CUDA for 2‑D transposed convolution
# ----------------------------------------------------------------------
conv_transpose2d_kernel_source = """
__global__ void conv_transpose2d_kernel(const float* in, const float* weight, float* out,
                                        int B, int C_in, int C_out, int H_in, int W_in,
                                        int stride, int padding, int dilation, int kH, int kW) {
    // Output resolution for transposed convolution
    int out_h = (H_in + 2*padding - dilation*(kH-1)) / stride + 1;
    int out_w = (W_in + 2*padding - dilation*(kW-1)) / stride + 1;
    int total_out = B * C_out * out_h * out_w;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_out) {
        // Decode output coordinates
        int b = idx / (C_out * out_h * out_w);
        int rem = idx % (C_out * out_h * out_w);
        int c_out = rem / (out_h * out_w);
        int rem2 = rem % (out_h * out_w);
        int oh = rem2 / out_w;
        int ow = rem2 % out_w;

        // Input patch top‑left corner
        int in_h_start = oh * stride - padding;
        int in_w_start = ow * stride - padding;

        float sum = 0.0f;
        for (int kh = 0; kh < kH; ++kh) {
            for (int kw = 0; kw < kW; ++kw) {
                int ih = in_h_start + kh * dilation;
                int iw = in_w_start + kw * dilation;
                if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                    // Placeholder: add weight contribution (weight layout assumed)
                    sum += weight[c_out, 0, kh, kw] * 1.0f;
                }
            }
        }
        out[idx] = sum;
    }
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor in, torch::Tensor weight, bool bias) {
    auto size = in.numel();
    auto out = torch::zeros_like(in);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        in.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        in.size(0), in.size(1), out_channels, in.size(2), in.size(3),
        stride, padding, dilation, kernel_size, kernel_size
    );

    return out;
}
"""

